  logic rx_busy;
  logic rx_overrun_error;
  logic rx_frame_error;

  // -------------------------------------------------
  // DUT instantiation (default parameters)
  // -------------------------------------------------
  uart #(.DATA_WIDTH(8)) dut (
    .clk               (clk),
    .rst               (rst),
    .s_axis_tdata      (s_axis_tdata),
    .s_axis_tvalid     (s_axis_tvalid),
    .s_axis_tready     (s_axis_tready),
    .m_axis_tdata      (m_axis_tdata),
    .m_axis_tvalid     (m_axis_tvalid),
    .m_axis_tready     (m_axis_tready),
    .rxd               (rxd),
    .txd               (),          // unused
    .tx_busy           (tx_busy),
    .rx_busy           (rx_busy),
    .rx_overrun_error  (rx_overrun_error),
    .rx_frame_error    (rx_frame_error),
    .prescale          (prescale)
  );

  // -------------------------------------------------
  // Main stimulus
  // -------------------------------------------------
  initial begin
    // Reset
    rst = 1;
    #100;
    rst = 0;

    // Small idle before stimulus
    #20;

    // -------------------------------------------------
    // Frame 1 : transmit 8'h3C (stall until accepted)
    // -------------------------------------------------
    // Start bit (low)
    rxd = 0;
    #(PRESCALE_VAL*8);
    // Data bits, LSB‑first
    for (int i = 0; i < 8; i++) begin
      rxd = (8'h3C >> i) & 1'b1;
      #(PRESCALE_VAL*8);
    end
    // Stop bit (high)
    rxd = 1;
    #(PRESCALE_VAL*8);

    // Wait until the DUT asserts m_axis_tvalid (word ready)
    wait (m_axis_tvalid);
    // Hold a couple of cycles so busy is still high and bit_cnt is in 2..9
    repeat (2) @(posedge clk);
    // Accept the word (release back‑pressure)
    m_axis_tready = 1;
    @(posedge clk);
    m_axis_tready = 0;

    // -------------------------------------------------
    // Frame 2 : transmit 8'hA5 (should be delivered with busy still high)
    // -------------------------------------------------
    // Small idle gap
    #(PRESCALE_VAL*8);
    // Start bit
    rxd = 0;
    #(PRESCALE_VAL*8);
    // Data bits for 8'hA5 (LSB‑first)
    for (int i = 0; i < 8; i++) begin
      rxd = (8'hA5 >> i) & 1'b1;
      #(PRESCALE_VAL*8);
    end
    // Stop bit
    rxd = 1;
    #(PRESCALE_VAL*8);

    // Allow a short settling period then finish
    #2000;
    $finish;
  end

endmodule

